<template>
   <div class="d-flex align-items-center justify-content-between flex-wrap gap-2">
    <h5 class="mb-0">
        UNBUDGETED EXPENSES FOR {{ ProjectName }}
    </h5>

    <div class="d-flex align-items-center gap-3 ms-auto">
        <span class="text-dark fs-6">
            Total Expenses: {{ formatRate(totalCost) }}
        </span>

        <button
            class="btn btn-success"
            @click="printUnbudgetedCosts(orders, ProjectId, ProjectName)"
            title="Print Unbudgeted Costs Report"
        >
            <i class="bi bi-printer fs-4"></i>
        </button>
    </div>
</div>


                      <div class="panel p-0 my-2">
        <div v-if="loading" v-html="tableShimmer()"></div>
        <div v-else class="custom-table">
          <v-client-table :data="orders" :columns="orderColumns" :options="table_option">

                          <template #actions="props">
                                
                                    <a href="javascript:;" class=" text-primary me-3" data-bs-toggle="modal"
            data-bs-target="#approvalChainModal"
            @click="selectedOrder = props.row">
                                           <i class = 'bi bi-eye fs-4' />
                                        </a>
                                
                            </template>
          </v-client-table>
        </div>
      </div>

       <approvalChainModal :OrderId="selectedOrder.order"/>

</template>

<script setup>
import { ref, onMounted, inject ,watch } from 'vue';
import { useRoute } from 'vue-router';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import approvalChainModal from '@/views/approvalChain/components/approvalChainModal.vue';

     const route = useRoute();
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });


    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 30, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });
    const printUnbudgetedCosts = inject('printUnbudgetedCosts')
    const selectedOrder = ref('');
    const formatDate = inject('formatDate')
     const formatRate = inject('formatRate')
     const formatNumber = inject('formatNumber')
    const tableShimmer = inject('tableShimmer')
    const showError = inject('showError')
 const loading = ref(false);
const orders = ref([])
const orderColumns = ref(['Sno','order','item','description','quantity','rate', 'requester','cost','date','actions']);
const totalCost = ref(0)

const getOrders = async(project_id) =>{
    loading.value = true
    try{
    const response = await axiosInstance.get(`unbudgeted-costs?project_id=${project_id}`)
    totalCost.value = response.data.total_cost ?? 0;
    orders.value = response.data.items.map((item,index)=>({
      ...item,
      Sno : index + 1,
      order : item.approval_id,
      item : item.remark,
      description:item.description,
      cost: formatRate(item.cost),
      quantity:formatNumber(item.quantity),
      rate:formatRate(item.rate),
      date:formatDate(item.created_at)
    }));
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
        loading.value = false
    }
}


const props = defineProps({
    ProjectId: String,
    ProjectName: String
});

watch(
    () => props.ProjectId,
    (newId) => {
        if (newId) {
            getOrders(newId);
        }
    },
    { immediate: true }
);

</script>