   const currentBudgetItem = ref('')
const getBudgetConsuption = async (desc,item) => {
  consuptions.value = [];
  loading.value = true;
  currentBudgetItem.value = item.name

  // initialize balance from desc.cost
  balance.value = parseFloat(desc.quantity * desc.quantity_2 * desc.cost);

  const response = await axiosInstance.get(
    `budget-remarks?budget_item_description_id=${desc.id}`
  );

  consuptions.value = response.data.map((data, i) => {
    balance.value -= parseFloat(data.cost);
    return {
      ...data,
      sno: i + 1,
      id: data.id,
      remarker : data.remarker.name,
      date: data.date,
      debit: data.cost > 0 ? Number(data.cost).toLocaleString() + " Tsh" : "--",
      credit:
        data.cost < 0
          ? Number(Math.abs(data.cost)).toLocaleString() + " Tsh"
          : "--",
      description: data.description,
      balance: balance.value.toLocaleString() + " Tsh",
    };
  });

  loading.value = false;
};



