<template>


                 <div class="modal fade mymodal" id="ipc-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-fullscreen">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel">{{props.project}} INTERIM PAYMENT CERTIFICATES </h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>
<div class="modal-body" >
            <div class="row layout-top-spacing">
          <div class="col-lg-12 col-sm-12 layout-spacing col-xl-12"
          >
                      <div         
            class="panel p-0" >
              <div class="custom-table table3"  >
<table class="table table-hover">
  <thead>
    <tr>
      <th scope="col">#</th>
      <th scope="col">Budget</th>
      <th scope="col">IPC Cost</th>
       <th scope="col">Actions</th>
    </tr>
  </thead>
<tbody>
    <tr v-for="(ipc, index) in ipcs" :key="index">
        <td>{{ index + 1 }}</td>
        <td>{{ ipc.budget }}</td>
        <td>{{ Number(ipc.ipc_value || 0).toLocaleString() }}</td>
        <td>
            <i
                class="bi fs-5 bi-eye text-primary"
                style="cursor:pointer"
                @click="openModalOnModal('boq-line-modal','ipc-modal'); ipcView = ipc"
            ></i>
        </td>
    </tr>

    <!-- Total -->
    <tr class="fw-bold">
        <td colspan="2" class="text-end">TOTAL</td>
        <td>{{ totalIpcValue.toLocaleString() }}</td>
        <td></td>
    </tr>
</tbody>
</table>
</div>
</div>
</div>

</div>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger btn-sm py-2 px-2" data-bs-dismiss="modal">Close</button>
      </div>

    </div>
  </div>

</div>


               <!-- ===== boq line modal ===-->
                <budgetBoqLineModal :budgetId="ipcView.id"/>
                <!-- ===== boq line modal ==== -->

</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const openModalOnModal = inject('openModalOnModal')

import budgetBoqLineModal from '@/views/projects/budgets/components/budgetBoqLineModal.vue';

const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    projectId: String,
    project : String
});

const loadingSpinner = inject('loadingSpinner')

const loading = ref(false)

const showError = inject('showError')
const showMessage = inject('showMessage')

const ipcs = ref(null)
const getIpcs = async (id)=>{
    try{
        const response = await axiosInstance.get(`get-ipcs?project_id=${id}`)
        ipcs.value = response.data
    }catch(error){
       console.log(error)
       showError(error.message)
    }
}

const ipcView = ref('')


    watch(
    () => props.projectId,
    (newId) => {
        if (newId) {
          getIpcs(newId)
        }
    },
    { immediate: true }
);

const totalIpcValue = computed(() => {
    return (ipcs.value || []).reduce((total, ipc) => {
        return total + Number(ipc.ipc_value || 0)
    }, 0)
})


    // onMounted(async() => {
    //     getIpcs()
    // });
</script>





