<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Work Order' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    import ipcs from './ipcs.vue';
const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    projectId: String,
});

const waitIndicator = inject('waitIndicator')

const loading = ref(false)

const showError = inject('showError')
const showMessage = inject('showMessage')

const summary = ref(null)
const getSummary = async (project_id)=>{
    loading.value = true
    try{
        const response = await axiosInstance.get(`project-summary?project_id=${project_id}`)
        summary.value = response.data
    }catch(error){
       console.log(error)
       showError(error.message)
    }finally{
        loading.value = false
    }
}

const pct = (a, b) => (b ? (a / b) * 100 : 0)

const p1 = (n) => `${n.toFixed(1)}%`

const tone = (n) => (n >= 0 ? 'text-success' : 'text-danger')

const tzs = (n) => {
    const v = Number(n) || 0
    const a = Math.abs(v)
    const sign = v < 0 ? '−' : ''
    if (a >= 1e9) return `${sign}TZS ${(a / 1e9).toFixed(3)}B`
    if (a >= 1e6) return `${sign}TZS ${(a / 1e6).toFixed(2)}M`
    return `${sign}TZS ${a.toLocaleString()}`
}

const s = computed(() => summary.value || {})

const m = computed(() => {
    const d = s.value
    const project = Number(d.project_value) || 0
    const budget = Number(d.budgeted_cost) || 0
    const used = Number(d.used_cost) || 0
    const unb = Number(d.unbudgeted_cost) || 0
    const ipc = Number(d.ipc_projections) || 0
    const spend = used + unb
    const gross = ipc - spend
    const grossNoUnb = ipc - used
    const flowBase = Math.max(ipc, spend)
    return {
        project, budget, used, unb, ipc, spend, gross, grossNoUnb,
        budgetRemaining: budget - used,
        overBudget: spend - budget,
        projectRemaining: project - ipc,
        usedOfIpc: pct(used, ipc),
        unbOfIpc: pct(unb, ipc),
        grossOfIpc: pct(gross, ipc),
        spendOfIpc: pct(spend, ipc),
        budgetOfIpc: pct(budget, ipc),
        unbOfSpend: pct(unb, spend),
        ipcOfProject: pct(ipc, project),
        budgetUsedPct: pct(used, budget),
        overBudgetPct: pct(spend - budget, budget),
        unbOfPotential: pct(unb, grossNoUnb),
        flowUsed: pct(used, flowBase),
        flowUnb: pct(unb, flowBase),
        flowGross: pct(Math.max(gross, 0), flowBase)
    }
})

    watch(
    () => props.projectId,
    (newId) => {
        if (newId) {
            getSummary(newId);
        }
    },
    { immediate: true }
);

</script>

