<template>


                     <div class="modal fade mymodal" id="budget-edit-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="staticBackdropLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content" >
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="staticBackdropLabel"> BUDGET EDITING FORM {{ budgetData.project }}</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" id="close" ></button>
      </div>
      <span v-if="loadingData" v-html="waitIndicator()"></span> 
              <form v-else @submit.prevent="updateBudget()">
<div class="modal-body" >
    <div  class="d-flex flex-column align-items-center">
        <div class = "row">
            <div class="col-md-5">
              <label class="form-label">Budget Name</label>
        <input 
          type="text" 
          class="form-control" 
          placeholder="Enter budget name"
          v-model="budget_name"
          required
        >
        </div>
        <div class="col-md-4">
        <label class="form-label">Length Of Section</label>
        <input 
          type="number" 
          class="form-control" 
          placeholder="Enter Length of section"
          v-model="section_length"
          step="any"
        >
        </div>

            <div class="col-md-3">
                            <label class="form-label">Unit</label>
                                   <Multiselect
        v-model="unit"
        :options="units"
        placeholder="Select section Unit"
        label="short_name"
        :searchable="true"        
        :append-to-body="true"
    />
        </div>

          <div class="col-md-12">
                          <label class="form-label">BOQ Lines</label>
                                   <Multiselect
        v-model="selectedBoqLines"
        :options="boqLines"
        label="name"
        placeholder="Select Boq Lines"
        :searchable="true"     
        :multiple="true"
        track-by="id"
    />
        </div>

                <div class="col-md-12">
                                <label class="form-label">Brief Description</label>
        <input 
          type="text" 
          class="form-control" 
          placeholder="Enter description"
          v-model="budget_descriptions"
        >
        </div>
        </div>

    </div>
    

      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-danger " data-bs-dismiss="modal">Close</button>
        <button 
          type="submit" 
          class="btn btn-primary me-2"
          :disabled="loading"
        >
     <span v-if="loading" v-html="loadingSpinner()"></span>
<span v-else>Update Budget</span>
        </button>
      </div>
  </form>
    </div>
  </div>

</div>


</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });
    const openModalOnModal = inject('openModalOnModal')



const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    budgetId: Number,
    projectId : String
});

const loadingSpinner = inject('loadingSpinner')

const loading = ref(false)

const showError = inject('showError')
const showMessage = inject('showMessage')
const waitIndicator = inject('waitIndicator')

    const units = ref([])
    const unit = ref('')
    const getUnits = async ()=>{
      const response = await axiosInstance.get('units')
      units.value = response.data
    }


    const section_length = ref('')
    const budget_descriptions = ref('')
    const budget_name = ref('')
    const boqLines = ref([])
    
    const loadingData = ref(false)
const fillModal = async () => {
  loadingData.value = true
    if (!budgetData.value || !boqLines.value.length) {
        await Promise.all([
            getBudgetData(),
            getBoqLines()
        ])    }
          loadingData.value = false
    section_length.value = budgetData.value.section_length
    budget_descriptions.value = budgetData.value.budget_descriptions
    unit.value =   units.value.find(unt => unt.name === budgetData.value.unit)
    budget_name.value = budgetData.value.budget

    selectedBoqLines.value = boqLines.value.filter(line =>
        budgetData.value.boq_lines?.some(selected =>
            selected.id === line.id ||
            selected.boq_line_id === line.id
        )
    )
}

const selectedBoqLines = ref([])
const getBoqLines = async()=>{
  try{
    const response = await axiosInstance.get(`project-boq-lines?project_id=${props.projectId}`)
    boqLines.value = response.data.data
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    
  }
}



const budgetData = ref('')
const getBudgetData = async(id)=>{
  loading.value = true
  try{
    const response = await axiosInstance.get(`budget-data?budget_id=${id}`)
    budgetData.value = response.data

    fillModal()
  }catch(error){
    showError(error.message)
    console.log(error)
  }finally{
    loading.value = false
  }
}

const updateBudget = async () => {
    loading.value = true

    try {
        const payload = {
            budget_name: budget_name.value,
            section_length: section_length.value,
            unit: unit.value?.name ?? unit.value,
            budget_descriptions: budget_descriptions.value,
            boq_lines: selectedBoqLines.value.map(line => ({
                id: line.id
            }))
        }

        await axiosInstance.put(
            `budgets/${budgetData.value.id}`,
            payload
        )

        showMessage('Budget updated successfully')

        document.getElementById('budget-edit-modal')
            ?.querySelector('[data-bs-dismiss="modal"]')
            ?.click()

        await getBudgetData(props.budgetId)

    } catch (error) {
        showError(error.response?.data?.message || error.message)
        console.log(error)
    } finally {
        loading.value = false
    }
}


watch(
    () => props.budgetId,
    async (newId) => {
        if (newId) {
        getBudgetData(newId)   }
    },
    { immediate: true }
);

watch(
    () => props.projectId,
    async (newId) => {
        if (newId) {
        getBoqLines(newId)   }
    },
    { immediate: true }
);



    onMounted(async() => {
        getUnits()
    });
</script>





